/**
 * HGhub Rex/Forward 黄果短剧模块图标 · Cloudflare Worker（hghub-hg）
 * /huangguo.png  （图标取自黄果站点 apple-touch-icon，放大到 256×256）
 */
const PNG = "";
export default {
  async fetch(request) {
    if (new URL(request.url).pathname !== "/huangguo.png") return new Response("not found", { status: 404 });
    const bin = Uint8Array.from(atob(PNG), (c) => c.charCodeAt(0));
    return new Response(bin, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400", "Access-Control-Allow-Origin": "*" } });
  },
};
